CREATE TABLE `resolvent_refinery` (
  `itemid` int(10) NOT NULL,
  `name` varchar(45) DEFAULT '',
  `base` int(10) NOT NULL DEFAULT '0',
  `base+1` int(10) NOT NULL DEFAULT '0',
  `base+2` int(10) NOT NULL DEFAULT '0',
  `base+3` int(10) NOT NULL DEFAULT '0',
  `base+4` int(10) NOT NULL DEFAULT '0',
  `base+5` int(10) NOT NULL DEFAULT '0',
  `base+6` int(10) NOT NULL DEFAULT '0',
  `base+7` int(10) NOT NULL DEFAULT '0',
  `base+8` int(10) NOT NULL DEFAULT '0',
  PRIMARY KEY (`itemid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

